// (trm 4096) the f16 gammas in place, in the f32 gammas' own words (their first half),
// made once on the first pass (the host places the weights after init, once)
var g1h_dsd = xph_dsd;
var g2h_dsd = xph_dsd;
var gh_done: bool = false;

if (!gh_done) {
  g1h_dsd = @set_dsd_base_addr(xph_dsd, @ptrcast([*]@fp16(), &gamma1));
  g2h_dsd = @set_dsd_base_addr(xph_dsd, @ptrcast([*]@fp16(), &gamma2));
  // in place: f16 i lands in word i / 2 <= i, already read
  @fs2h(@set_dsd_length(g1h_dsd, NL * Hc), g1_all);
  @fs2h(@set_dsd_length(g2h_dsd, NL * Hc), g2_all);
  gh_done = true;
}
